package com.imageseal.controller;
import com.imageseal.entity.*;import com.imageseal.repository.*;import com.imageseal.security.UserPrincipal;import com.imageseal.service.ImageStorageService;import com.imageseal.service.ImageValidationService;import com.imageseal.service.Sha256Service;import jakarta.transaction.Transactional;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/images/{imageId}/versions") public class ImageVersionController {
 private final ImageRepository images;private final ImageVersionRepository versions;private final UserRepository users;private final ImageStorageService storage;private final ImageValidationService validator;private final Sha256Service sha256;
 public ImageVersionController(ImageRepository i,ImageVersionRepository v,UserRepository u,ImageStorageService storage,ImageValidationService validator,Sha256Service sha256){images=i;versions=v;users=u;this.storage=storage;this.validator=validator;this.sha256=sha256;}
 private Map<String,Object> dto(ImageVersion v){return Map.ofEntries(Map.entry("id",v.getId()),Map.entry("original_image_id",v.getOriginal().getId()),Map.entry("version_number",v.getVersionNumber()),Map.entry("name",v.getName()),Map.entry("mime_type",v.getMimeType()),Map.entry("file_size",v.getFileSize()),Map.entry("storage_path",v.getId()),Map.entry("sha256",v.getSha256()),Map.entry("created_at",v.getCreatedAt()),Map.entry("width",0),Map.entry("height",0));}
 @GetMapping public List<Map<String,Object>> list(@PathVariable String imageId,@AuthenticationPrincipal UserPrincipal p){images.findByIdAndOwnerId(imageId,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));return versions.findAllByOriginalIdAndOwnerIdOrderByVersionNumberAsc(imageId,p.id()).stream().map(this::dto).toList();}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> add(@PathVariable String imageId,@RequestPart("file")MultipartFile f,@AuthenticationPrincipal UserPrincipal p)throws Exception{validator.validate(f);ImageRecord original=images.findByIdAndOwnerId(imageId,p.id()).orElseThrow(()->new NoSuchElementException("Image not found"));var existing=versions.findAllByOriginalIdAndOwnerIdOrderByVersionNumberAsc(imageId,p.id());int number=existing.stream().mapToInt(ImageVersion::getVersionNumber).max().orElse(1)+1;String id=UUID.randomUUID().toString();String rel=p.id()+"/versions/"+id+("image/png".equals(f.getContentType())?".png":".jpg");byte[] bytes=f.getBytes();storage.write(rel,bytes);try{String hash=sha256.hash(bytes);String name=Path.of(Objects.requireNonNullElse(f.getOriginalFilename(),"image")).getFileName().toString();return dto(versions.save(new ImageVersion(users.findById(p.id()).orElseThrow(),original,number,name,f.getContentType(),f.getSize(),rel,hash)));}catch(Exception e){storage.delete(rel);throw e;}}
 @DeleteMapping("/{versionId}") @Transactional public ResponseEntity<Void> delete(@PathVariable String imageId,@PathVariable String versionId,@AuthenticationPrincipal UserPrincipal p)throws Exception{ImageVersion v=versions.findByIdAndOwnerId(versionId,p.id()).filter(x->x.getOriginal().getId().equals(imageId)).orElseThrow(()->new NoSuchElementException("Image version not found"));storage.delete(v.getStoragePath());versions.delete(v);return ResponseEntity.noContent().build();}
}
